//! `cargo xtask notices` (NFR-LEG-05, ADR-0014): writes `THIRD_PARTY_NOTICES` from
//!
//! - the Rust crates in the shipped binaries (`cargo metadata`, normal dependencies of
//!   `mangkon-desktop` and `mangkon-cli` on every desktop target),
//! - the native sources compiled in (`crates/mk-tesseract-sys/native/sources.toml`),
//! - the npm packages bundled into the UI (`ui/package-lock.json`, non-dev entries).
//!
//! `--check` fails if the committed file differs, so CI catches a dependency change without a
//! regenerated file. The output is sorted and has no dates, so it is stable.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

use serde::Deserialize;

use crate::layers::{Kinds, Metadata};

pub const SHIPPED: &[&str] = &["mangkon-desktop", "mangkon-cli"];

#[derive(Deserialize)]
struct Sources {
    source: Vec<Source>,
}

#[derive(Deserialize)]
struct Source {
    name: String,
    version: String,
    license: String,
    homepage: String,
}

#[derive(Deserialize)]
struct Lock {
    packages: BTreeMap<String, LockEntry>,
}

#[derive(Deserialize)]
struct LockEntry {
    version: Option<String>,
    license: Option<String>,
    #[serde(default)]
    dev: bool,
}

/// One line per item: "name version" → (license, where from).
type Section = BTreeMap<String, (String, String)>;

pub fn render(root: &Path, metas: &[Metadata]) -> Result<String, String> {
    let mut rust = Section::new();
    for meta in metas {
        for member in &meta.workspace_members {
            if !SHIPPED.contains(&meta.name(member)) {
                continue;
            }
            for (id, _) in meta.reach(member, Kinds::Runtime, false, |_| false) {
                if meta.workspace_members.iter().any(|m| m == id) {
                    continue;
                }
                let p = meta.packages.iter().find(|p| p.id == id).unwrap();
                let license = p.license.clone().unwrap_or_else(|| "see crate".into());
                let repo = p.repository.clone().unwrap_or_default();
                rust.insert(format!("{} {}", p.name, p.version), (license, repo));
            }
        }
    }

    let sources_path = root.join("crates/mk-tesseract-sys/native/sources.toml");
    let sources: Sources = read_toml(&sources_path)?;
    let native: Section = sources
        .source
        .into_iter()
        .map(|s| (format!("{} {}", s.name, s.version), (s.license, s.homepage)))
        .collect();

    let lock_path = root.join("ui/package-lock.json");
    let lock: Lock = serde_json::from_str(&read(&lock_path)?)
        .map_err(|e| format!("{}: {e}", lock_path.display()))?;
    let mut npm = Section::new();
    for (key, e) in lock.packages {
        let Some(name) = key
            .rsplit("node_modules/")
            .next()
            .filter(|_| key.contains("node_modules/"))
        else {
            continue;
        };
        if e.dev {
            continue;
        }
        let version = e.version.unwrap_or_default();
        let license = e.license.unwrap_or_else(|| "see package".into());
        npm.insert(format!("{name} {version}"), (license, String::new()));
    }

    let mut out = String::from(
        "THIRD_PARTY_NOTICES for Mangkon AI\n\
         Generated by `cargo xtask notices`. Do not edit by hand.\n\
         \n\
         Mangkon AI is licensed under AGPL-3.0-only (see LICENSE). The app includes the\n\
         third-party components below, each under its own license.\n",
    );
    section(&mut out, "Native code compiled into the app", &native);
    section(&mut out, "Rust crates", &rust);
    section(&mut out, "npm packages bundled into the UI", &npm);
    Ok(out)
}

fn section(out: &mut String, title: &str, items: &Section) {
    let _ = write!(out, "\n## {title} ({})\n\n", items.len());
    for (name, (license, link)) in items {
        let _ = write!(out, "{name} | {license}");
        if !link.is_empty() {
            let _ = write!(out, " | {link}");
        }
        out.push('\n');
    }
}

fn read(path: &Path) -> Result<String, String> {
    std::fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))
}

fn read_toml<T: for<'de> Deserialize<'de>>(path: &Path) -> Result<T, String> {
    toml::from_str(&read(path)?).map_err(|e| format!("{}: {e}", path.display()))
}
